def need(value,label):
 if value is not True:raise ValueError('Task72_route_refused:'+label)
def digest(value):return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def route_metadata():return {'schema':SCHEMA,'count':72,'description_count':39,'source_snapshot_count':33,'mapping':[{'old':a,'new':b}for a,b in ROUTES],'mapping_sha256':digest(ROUTES),'retained_source_ids':list(RETAINED42),'default_refusal_ids':list(DEFAULT_BOUNDARIES)}
def _rows(rows):
 need(type(rows)is list and bool(rows),'nonempty_inventory')
 for row in rows:need(type(row)is dict and set(row)=={'id','module'}and type(row['id'])is str and type(row['module'])is str and row['id'].startswith(row['module']+'.'),'row_shape')
 ids=[r['id']for r in rows];need(len(set(ids))==len(ids),'duplicate_id');return ids

def _closed(rows,routed):
 ids=_rows(rows);old={a for a,b in ROUTES};new={b for a,b in ROUTES}
 need(len(ROUTES)==72 and len(DESCRIPTION39)==39 and len(SOURCE33)==33 and len(old)==len(new)==72 and not old&new,'bijection')
 by={}
 for row in rows:by.setdefault(row['module'],set()).add(row['id'])
 for module in OLD_DESCRIPTION_MODULES:
  expected={a for a,b in DESCRIPTION39 if a.split('.')[0]==module};need(by.get(module,set())==(set()if routed else expected),'old_description_module')
 for module in {b.split('.')[0]for a,b in DESCRIPTION39}:
  need(by.get(module,set())=={b for a,b in DESCRIPTION39 if b.split('.')[0]==module},'new_description_module')
 need(by.get(SOURCE_MODULE,set())==set(RETAINED42)|(set()if routed else{a for a,b in SOURCE33}),'retained_source42_and_old33')
 current='test_source_operation_snapshot_task_v2';assessment='test_source_snapshot_assessment_task_v2'
 need(by.get(current,set())=={b for a,b in SOURCE33 if b.split('.')[0]==current}|set(DEFAULT_BOUNDARIES),'new_current24_plus_default2')
 need(by.get(assessment,set())=={b for a,b in SOURCE33 if b.split('.')[0]==assessment},'new_assessment9')
 need(set(DEFAULT_BOUNDARIES)<=set(ids),'default_boundaries_retained')
 return old

def _leaves(node):
 if type(node)is unittest.TestSuite:
  result=[]
  for child in node:result.extend(_leaves(child))
  return result
 need(isinstance(node,unittest.TestCase),'custom_suite_or_leaf');return[node]

def route_groups(groups,full):
 need(type(groups)is list,'groups');seen=set();flat=[]
 for group in groups:
  need(type(group)is tuple and len(group)==3,'group_shape');module,suite,rows=group
  need(type(module)is str and module not in seen and type(rows)is list and bool(rows),'unique_module');seen.add(module)
  need(all(row['module']==module for row in rows),'whole_module');flat.extend(rows)
 need(flat==full,'original_discovery_order');old=_closed(full,False);out=[]
 for module,suite,rows in groups:
  if module in OLD_DESCRIPTION_MODULES:continue
  if module==SOURCE_MODULE:
   leaves=_leaves(suite);observed=[{'id':t.id(),'module':t.__class__.__module__}for t in leaves]
   need(observed==rows,'actual_original_source_suite_inventory')
   selected=[t for t in leaves if t.id()not in old];kept=[row for row in rows if row['id']not in old]
   need([t.id()for t in selected]==[row['id']for row in kept],'exact_source33_filter')
   # This single wrapper changes, leaves are identical and order preserved.
   out.append((module,unittest.TestSuite(selected),kept))
  else:out.append((module,suite,rows))
 chosen=[r for m,s,rs in out for r in rs];need(chosen==[r for r in full if r['id']not in old],'only_exact72_removed');_closed(chosen,True)
 return out,chosen,route_metadata()
def validate_routed_inventory(full,metadata):
 need(type(metadata)is dict and metadata==route_metadata(),'closed_exact72_metadata');_closed(full,True);return True
